(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const $ = id => document.getElementById(id);
  const WORLD = {w:2600,h:1900};
  const keys = new Set(), mouse = {x:innerWidth/2,y:innerHeight/2,down:false};
  const player = {x:1230,y:990,r:13,hp:100,armor:45,energy:72,speed:210,angle:0,ammo:24,reserve:96,meds:2,stims:1,grenades:2,weapon:0,dead:false,invuln:0};
  const weapons = [
    {name:'K-47',nick:'RUSTMAKER',type:'ASSAULT RIFLE',damage:26,rate:.19,spread:.055,mag:24,range:610,color:'#d5fa4c'},
    {name:'V-9',nick:'GHOSTLINE',type:'SMART PISTOL',damage:40,rate:.32,spread:.025,mag:12,range:490,color:'#72d9c9'}
  ];
  let cam={x:0,y:0}, time=0,last=performance.now(),fireCooldown=0,reloadTimer=0,toastTimer=0,enemyKills=0,missionDone=false, gameStarted=false, menuOpen=false,worldClock=0;
  const obstacles=[], props=[], caches=[], enemies=[], bullets=[], particles=[], drops=[];
  const rand=(a,b)=>a+Math.random()*(b-a), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function seedWorld(){
    // Scattered, traversable remains of a forgotten highway town.
    const buildings=[
      [340,230,260,150,'MOTEL'],[850,170,210,170,'AUTO'],[1630,250,265,165,'DUST'],[2070,500,270,190,'DINER'],
      [400,850,205,225,'DEPOT'],[1660,910,260,200,'RELAY'],[2070,1300,290,190,'HOSPITAL'],[800,1430,250,160,''],[1240,450,125,95,'']
    ];
    buildings.forEach(([x,y,w,h,label],i)=>{obstacles.push({x,y,w,h,type:'building',label});props.push({x,y,w,h,label,seed:i});});
    // Rubble and wrecks are both scenery and cover.
    for(let i=0;i<60;i++){
      const x=rand(90,WORLD.w-90),y=rand(90,WORLD.h-90);
      if(obstacles.some(o=>x>o.x-30&&x<o.x+o.w+30&&y>o.y-30&&y<o.y+o.h+30))continue;
      const type=['rock','wreck','scrap','cactus'][Math.floor(rand(0,4))],r=type==='wreck'?rand(18,30):rand(7,17);
      props.push({x,y,r,type,rot:rand(0,Math.PI*2),seed:i});if(type==='rock'||type==='wreck')obstacles.push({x:x-r,y:y-r,w:r*2,h:r*2,type:'cover'});
    }
    const cacheSpots=[[600,500],[1170,280],[1440,690],[1900,770],[1150,1230],[560,1260],[1820,1510],[2270,960],[330,1520]];
    cacheSpots.forEach((p,i)=>caches.push({x:p[0],y:p[1],opened:false,kind:['ARMORY','FIELD CACHE','OLD WORLD STASH'][i%3],gear:i%4===0?'armor':i%4===1?'ammo':i%4===2?'med':'weapon'}));
    const names=['Vex','Morrow','Saint','Juno','Knox','Hex','Sable','Rook','Ash','Cipher','Mack','Zero'];
    for(let i=0;i<9;i++){
      let x,y,tries=0;do{x=rand(240,WORLD.w-240);y=rand(200,WORLD.h-200);tries++;}while((dist({x,y},player)<430||obstacles.some(o=>x>o.x-30&&x<o.x+o.w+30&&y>o.y-30&&y<o.y+o.h+30))&&tries<100);
      enemies.push({x,y,r:12,hp:65,max:65,name:names[i],angle:rand(0,6.28),state:'roam',targetX:x,targetY:y,fire:rand(.8,2),speed:rand(50,74),dead:false,loot:false,phase:rand(0,6.28)});
    }
  }
  seedWorld();
  function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}addEventListener('resize',resize);resize();
  function message(text,danger=false){const el=document.createElement('div');el.className='log-line'+(danger?' danger':'');el.textContent=text;$('combatLog').prepend(el);while($('combatLog').children.length>4)$('combatLog').lastChild.remove();setTimeout(()=>el.remove(),4500);}
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=2.2;}
  function rectHit(x,y,r,o){const nx=clamp(x,o.x,o.x+o.w),ny=clamp(y,o.y,o.y+o.h);return Math.hypot(x-nx,y-ny)<r;}
  function blocked(x,y,r){return obstacles.some(o=>rectHit(x,y,r,o));}
  function moveEntity(entity,dx,dy,r){if(!blocked(entity.x+dx,entity.y,r))entity.x+=dx;if(!blocked(entity.x,entity.y+dy,r))entity.y+=dy;entity.x=clamp(entity.x,r,WORLD.w-r);entity.y=clamp(entity.y,r,WORLD.h-r);}
  function setHud(){const pct=(v,max)=>`${Math.max(0,v/max*100)}%`;$('healthNum').textContent=Math.ceil(player.hp);$('armorNum').textContent=Math.ceil(player.armor);$('energyNum').textContent=Math.ceil(player.energy);$('healthBar').style.width=pct(player.hp,100);$('armorBar').style.width=pct(player.armor,100);$('energyBar').style.width=pct(player.energy,100);$('ammo').innerHTML=`${player.ammo}<span> / ${player.reserve}</span>`;$('medCount').textContent=player.meds;$('stimCount').textContent=player.stims;$('grenadeCount').textContent=player.grenades;$('weaponName').innerHTML=`${weapons[player.weapon].name} <i>${weapons[player.weapon].nick}</i>`;$('threatCount').textContent=String(enemies.filter(e=>!e.dead&&dist(e,player)<570).length).padStart(2,'0');}
  function nearestInteract(){let found=null,d=68;for(const c of caches)if(!c.opened&&dist(c,player)<d){found=c;d=dist(c,player);}for(const e of enemies)if(e.dead&&!e.loot&&dist(e,player)<d){found=e;d=dist(e,player);}if(!missionDone&&dist({x:1780,y:1010},player)<d){found={x:1780,y:1010,mission:true};}return found;}
  function doInteract(){const target=nearestInteract();if(!target)return;if(target.mission){missionDone=true;player.energy=Math.min(100,player.energy+28);toast('SIGNAL CORE RECOVERED  ·  CONTRACT COMPLETE');message('RELAY SIGNAL SECURED. REWARD: 240¢ + NEURAL CHIP');$('objective').textContent='SIGNAL CORE RECOVERED';return;}if(target.dead){target.loot=true;const reward=Math.random();if(reward<.4){player.ammo+=28;toast(`LOOTED ${target.name}  ·  +28 RIFLE AMMO`);}else if(reward<.7){player.armor=Math.min(100,player.armor+22);toast(`LOOTED ${target.name}  ·  ARMOR PLATE +22`);}else{player.meds++;toast(`LOOTED ${target.name}  ·  MED PATCH`);}return;}target.opened=true;let text='';if(target.gear==='armor'){player.armor=Math.min(100,player.armor+38);text='CERAMIC PLATE +38';}else if(target.gear==='ammo'){player.ammo+=18;player.reserve+=48;text='AMMO +18  ·  RESERVE +48';}else if(target.gear==='med'){player.meds++;player.hp=Math.min(100,player.hp+20);text='MED PATCH +1  ·  INTEGRITY +20';}else{player.weapon=1;player.ammo=Math.max(player.ammo,12);text='V-9 GHOSTLINE SMART PISTOL';}toast(`${target.kind}  ·  ${text}`);message(`SCAVENGED ${target.kind}: ${text}`);}
  function shoot(){if(!gameStarted||player.dead||menuOpen||fireCooldown>0||reloadTimer>0)return;if(player.ammo<=0){toast('MAGAZINE EMPTY  ·  PRESS R TO RELOAD');fireCooldown=.3;return;}const w=weapons[player.weapon];player.ammo--;fireCooldown=w.rate;const spread=(Math.random()-.5)*w.spread;const a=player.angle+spread,sx=player.x+Math.cos(a)*16,sy=player.y+Math.sin(a)*16;bullets.push({x:sx,y:sy,vx:Math.cos(a)*680,vy:Math.sin(a)*680,life:w.range/680,from:'player',damage:w.damage,color:w.color});for(let i=0;i<4;i++)particles.push({x:sx,y:sy,vx:rand(-45,45),vy:rand(-45,45),life:.13,color:'#e9e9bd',size:rand(1,3)});}
  function reload(){const w=weapons[player.weapon];if(reloadTimer||player.ammo>=w.mag||player.reserve<=0)return;reloadTimer=1.2;message('RELOADING');}
  function damagePlayer(amount){if(player.invuln>0)return;const absorb=Math.min(player.armor,amount*.65);player.armor-=absorb;player.hp-=amount-absorb;player.invuln=.22;if(player.hp<=0){player.hp=0;player.dead=true;$('deathOverlay').classList.remove('hidden');message('SIGNAL LOST',true);}}
  function hitEnemy(e,damage){e.hp-=damage;for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:rand(-75,75),vy:rand(-75,75),life:rand(.2,.48),color:'#e9614e',size:rand(2,4)});if(e.hp<=0){e.dead=true;enemyKills++;message(`${e.name.toUpperCase()} DOWN  ·  HOLD E TO SCAVENGE`,true);for(let i=0;i<12;i++)particles.push({x:e.x,y:e.y,vx:rand(-110,110),vy:rand(-110,110),life:rand(.25,.65),color:i%2?'#a23e33':'#d7c89b',size:rand(2,5)});}}

